xc_mapping_rows(a65b16526aa550,[]).
x_comment(x_VisualAwareness,"The degree of awareness which specifies that an agent X is aware of (knows something about) some individual object's physical appearance.") :- x_cid(a65b16526aa551).
xc_microtheory(a65b16526aa551,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa551,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
