xc_mapping_rows(a65b16526aa5b1,[]).
x_comment(x_significanceOfSituation,"(#$significanceOfSituation SITUATION GVP) indicates that\nSITUATION has the degree of significance indicated by GVP. For example, \n(#$significanceOfSituation #$GettysburgAddress-Speech #$highAmountOf) indicates\nthat the Gettysburg address is considered significant.") :- x_cid(a65b16526aa5b2).
xc_microtheory(a65b16526aa5b2,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa5b2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
