xc_mapping_rows(a65b16526aa5c0,[]).
x_comment(x_ambientAtmosphericConcentration,"(#$ambientAtmosphericConcentration PLACE STUFF CONCENTRATION) holds just in case the concentation of the substance type STUFF is CONCENTRATION in the ambient atmospere in PLACE.  For instance, (#$ambientAtmosphericConcentration MyOffice #$Cyanide ((#$PerFn #$Gram #$CubicCentimeter) .003)) holds just in case the ambient atmospheric concentration of #$Cyanide in MyOffice is .003 grams per cubit centimeter.") :- x_cid(a65b16526aa5c1).
xc_microtheory(a65b16526aa5c1,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa5c1,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
