xc_mapping_rows(a65b16526aa5c1,[]).
x_comment(x_levelOfOutputOfType,"(#$levelOfOutputOfType EVT TYPE AMOUNT) says that EVT produced\nAMOUNT instances of TYPE.  For example (#$levelOfOutputOfType\nCowMilking001 #$CowsMilk-Product #$veryLowAmountOf) says that CowMilking001\nproduced very little milk.") :- x_cid(a65b16526aa5c2).
xc_microtheory(a65b16526aa5c2,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa5c2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
