xc_mapping_rows(a65b16526aa5cb,[]).
x_comment(x_durationAtIntensityLevel,"(#$durationAtIntensityLevel COND DIS-LEV TIME) means that the agent experiencing (#$bodilyDoer) COND has experienced the level of discomfort DIS-LEV for the time period TIME.") :- x_cid(a65b16526aa5cc).
xc_microtheory(a65b16526aa5cc,x_UniversalVocabularyMt).
