xc_mapping_rows(a65b16526aa63b,[]).
x_comment(x_MassEMailSending,"A specialization of #$EMailSending. Each instance of this collection is an event in which somebody or something sends copies of an #$EMailMessage to many -- dozens to thousands -- of #$EMailAddresses. Cf. #$MassEMailCommunication.") :- x_cid(a65b16526aa63c).
xc_microtheory(a65b16526aa63c,x_UniversalVocabularyMt).
