xc_mapping_rows(a65b16526aa85a,[]).
x_comment(x_fileCopyContents,"(#$fileCopyContents FILECOPY INFO) means that INFO is an abstract piece of information (an instance of #$AspatialInformationStore) contained in the #$ComputerFileCopy FILECOPY.") :- x_cid(a65b16526aa85b).
xc_microtheory(a65b16526aa85b,x_UniversalVocabularyMt).
