xc_mapping_rows(a65b16526aa85f,[]).
x_comment(x_remainsAtEventLocation,"(remainsAtEventLocation EVENT OBJ) means that OBJ was located at the instance of #$EnduringThing-Localized at which EVENT occured during EVENT and remains in that location after EVENT has taken place without leaving that location.") :- x_cid(a65b16526aa860).
xc_microtheory(a65b16526aa860,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa860,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
