x_comment(x_Afternoon,"A specialization of #$QualitativeTimeOfDay. An instance of this collection is the daily celestial event in which the #$Sun moves from its `highest' position in the daily cycle and `sets' or becomes a #$MidnightSun, i.e from noon till #$Sunset or #$MidnightSun.  Each #$Afternoon is #$temporallyFinishedBy a #$Sunset or #$MidnightSun.") :- x_cid(a65b16526aa861).
xc_microtheory(a65b16526aa861,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa861,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aa861,23969).
xc_kb_names(a65b16526aa861,[]).
xc_mapping_rows(a65b16526aa861,[]).
x_comment(x_Evening,"A specialization of #$QualitativeTimeOfDay. An instance of this collection is a regularly recurring celestial event started by an instance of #$Dusk and #$temporallyCoterminal with the #$CalendarDay of which it is a part. ") :- x_cid(a65b16526aa862).
xc_microtheory(a65b16526aa862,x_UniversalVocabularyMt).
