xc_kb_names(a65b16526aa8a0,[]).
xc_mapping_rows(a65b16526aa8a0,[]).
x_comment(x_JournalSeries,"A periodical dealing especially with areas of current interest.") :- x_cid(a65b16526aa8a1).
xc_microtheory(a65b16526aa8a1,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa8a1,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
