xc_mapping_rows(a65b16526aa8a6,[]).
x_comment(x_InterAnimalRelationPredicate,"An instance of #$PredicateType and a specialization of #$InterExistingObjectPredicate.  Each instance of #$InterAnimalRelationPredicate is a certain relationship between two #$Animals.  Instances of this collection include #$mate, #$friends, and #$boss.") :- x_cid(a65b16526aa8a7).
xc_microtheory(a65b16526aa8a7,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa8a7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
