xc_kb_names(a65b16526aa8aa,[]).
xc_mapping_rows(a65b16526aa8aa,[]).
x_comment(x_containsInformation,"A binary predicate that relates instances of #$InformationStore to instances of #$AspatialInformationStore. (#$containsInformation IS INFO) means that INFO is part of the information content of the #$InformationStore, IS. See also #$containsInfoPropositional-IBT. For assertions that a given IBT contains information about a given #$Thing, see #$containsInformationAbout and its specializations.") :- x_cid(a65b16526aa8ab).
xc_microtheory(a65b16526aa8ab,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa8ab,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
