xc_mapping_rows(a65b16526aa8ad,[]).
x_comment(x_ExampleFn,"This funtion is meant to be used only in #$examplePredSentences and #$exampleNATs assertions.  (ExampleFn #$AdultFemaleHuman) means \"some woman\", and could be used to exemplify what's an acceptable arg2 for #$mother.") :- x_cid(a65b16526aa8ae).
xc_microtheory(a65b16526aa8ae,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa8ae,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
