xc_mapping_rows(a65b16526aa8b9,[]).
x_comment('x_typesHaveRelationInSituationType-Existential',"(#$typesHaveRelationInSituationType-Existential SIT-TYPE TYPE1 TYPE2 BINREL) means that in any instance of SIT-TYPE, there are instances of TYPE1 and TYPE2 such that it will hold throughout the instance (see #$holdsIn) that the instance of TYPE1 has the relation BINREL to the instance of TYPE2.") :- x_cid(a65b16526aa8ba).
xc_microtheory(a65b16526aa8ba,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa8ba,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aa8ba,24063).
xc_kb_names(a65b16526aa8ba,[]).
xc_mapping_rows(a65b16526aa8ba,[]).
x_comment('x_inFrontOf-Directly',"An instance of #$RelativeLocationalPredicate.  (#$inFrontOf-Directly FORE AFT) means that the #$SpatialThing-Localized FORE is directly in front of the #$PartiallyTangible AFT.  More precisely, (#$inFrontOf-Directly FORE AFT) implies both (#$inFrontOf-Generally FORE AFT), and that there is at least one line parallel to the forward pointing axis of AFT that intersects both FORE and AFT.  Note that FORE may be an intangible thing, such as an image projected onto a screen.") :- x_cid(a65b16526aa8bb).
xc_microtheory(a65b16526aa8bb,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa8bb,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aa8bb,24064).
