xc_mapping_rows(a65b16526aa8be,[]).
x_comment(x_subSituationTypeList,"'(#$subSituationTypeList SIT-TYPE LIST)' means that LIST is a #$List of subsituation types in SIT-TYPE such that each member in\nLIST #$startsAfterEndOfInSituationType the earlier members in LIST.") :- x_cid(a65b16526aa8bf).
xc_microtheory(a65b16526aa8bf,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa8bf,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
