xc_mapping_rows(a65b16526aa986,[]).
x_comment(x_ArrangingObjects,"A specialization of #$LocatingInIntendedPosition and #$ConfiguringEvent.  Each instance of #$ArrangingObjects is an event in which an agent deliberately places physical objects in a desired #$Configuration.") :- x_cid(a65b16526aa987).
xc_microtheory(a65b16526aa987,x_UniversalVocabularyMt).
xc_source_file(a65b16526aa987,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
