xc_kb_names(a65b16526aab68,[]).
xc_mapping_rows(a65b16526aab68,[]).
x_comment(x_birthPlace,"<code>(#$birthPlace ANIMAL PLACE)</code> means that <code>ANIMAL</code> was born in the location <code>PLACE</code>.  <code>PLACE</code> may be any instance of #$Place, such as a building or a geographical location.") :- x_cid(a65b16526aab69).
xc_microtheory(a65b16526aab69,x_UniversalVocabularyMt).
xc_source_file(a65b16526aab69,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
