xc_mapping_rows(a65b16526aabda,[]).
x_comment(x_biologicalOffspring,"A specialization of #$biologicalRelatives.  <code>(#$biologicalOffspring PARENT OFFSPRING)</code> means that <code>PARENT</code> is one of the biological parents of <code>OFFSPRING</code>.  Specializations of this predicate include #$biologicalDaughters and #$biologicalSons.  Cf. #$children.") :- x_cid(a65b16526aabdb).
