xc_kb_names(a65b16526aac12,[]).
xc_mapping_rows(a65b16526aac12,[]).
x_comment('x_Injury-Object',"Mechanical damage to (a portion of) the body.\n<p>\nSee #$IncurringAnInjury for the action of incurring an injury, and #$InjuryCondition for the condition of being injured.") :- x_cid(a65b16526aac13).
xc_microtheory(a65b16526aac13,x_UniversalVocabularyMt).
xc_source_file(a65b16526aac13,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
