xc_kb_names(a65b16526aac2b,[]).
xc_mapping_rows(a65b16526aac2b,[]).
x_comment(x_conservativeViaArgInverse,"A #$MetaPredicate that is a generalization of #$transitiveViaArgInverse (q.v.) in that it can take <i>any</i> binary predicate (transitive or not) as its second argument.  <code>(#$conservativeViaArgInverse PRED RELN N)</code> means that if both of these hold:\n<pre>\n  (PRED ... ARGN ... )\n  (RELN NEW-ARGN ARGN),\n</pre>\n<p>\nthen so does\n<pre>\n  (PRED ... NEW-ARGN ...)\n</pre>\n(where the argument-sequence <code>... NEW-ARGN ...</code> is just like <code>... ARGN ...</code> except for having <code>NEW-ARGN</code> in place of <code>ARGN)</code>.\n<p>\nNote that if <code>RELN</code> is a #$TransitiveBinaryPredicate, the more specialized #$transitiveViaArgInverse can be used instead.  See also #$conservativeViaArg.") :- x_cid(a65b16526aac2c).
xc_microtheory(a65b16526aac2c,x_UniversalVocabularyMt).
xc_source_file(a65b16526aac2c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aac2c,25651).
xc_kb_names(a65b16526aac2c,[]).
xc_mapping_rows(a65b16526aac2c,[]).
x_disjointWith(x_CycLAtomicTerm,x_CycLFormula) :- x_cid(a65b16526aac2d).
