x_comment(x_topicOfInfoTransfer,"The predicate #$topicOfInfoTransfer is used to indicate what a particular communication is about.  <code>(#$topicOfInfoTransfer TRANS TOPIC)</code> means that <code>TOPIC</code> is a primary topic of the information communicated in the #$InformationTransferEvent <code>TRANS</code>.  For example, a result reported after an instance of #$BloodTest will contain information about the #$objectTested (viz., the blood sample); the patient's blood is thus a #$topicOfInfoTransfer of that report.") :- x_cid(a65b16526aad05).
xc_microtheory(a65b16526aad05,x_UniversalVocabularyMt).
xc_source_file(a65b16526aad05,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aad05,26543).
xc_kb_names(a65b16526aad05,[]).
xc_mapping_rows(a65b16526aad05,[]).
x_comment(x_objectTested,"<code>(#$objectTested EVAL OBJ)</code> means that the #$PartiallyTangible <code>OBJ</code> is an object tested in the #$Evaluating <code>EVAL</code>.  For example, the portion of blood used to run a blood test fills the role of #$objectTested in that test.") :- x_cid(a65b16526aad06).
xc_microtheory(a65b16526aad06,x_UniversalVocabularyMt).
xc_source_file(a65b16526aad06,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
