xc_mapping_rows(a65b16526aad51,[]).
x_comment(x_resourceTypeAvailable,"(#$resourceTypeAvailable AGENT RESOURCE) means that AGENT has RESOURCE available to it.") :- x_cid(a65b16526aad52).
xc_microtheory(a65b16526aad52,x_UniversalVocabularyMt).
xc_source_file(a65b16526aad52,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
