xc_mapping_rows(a65b16526aad66,[]).
x_comment(x_bondIssuedBy,"(#$bondIssuedBy BOND AGENT) means that BOND is a #$Bond-Agreement that was issued by AGENT.") :- x_cid(a65b16526aad67).
