xc_mapping_rows(a65b16526aad7e,[]).
x_comment(x_storedOnMedium,"(#$storedOnMedium DATA-ARTIFACT MEDIUM) means that DATA-ARTIFACT is stored on MEDIUM.  Using this predicate the storage location of any instance of #$ComputerDataArtifact can be specified.") :- x_cid(a65b16526aad7f).
xc_microtheory(a65b16526aad7f,x_UniversalVocabularyMt).
xc_source_file(a65b16526aad7f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
