xc_kb_names(a65b16526aad85,[]).
xc_mapping_rows(a65b16526aad85,[]).
x_comment(x_TechnologyOrganization,"The collection of all instances of #$Business that are primarily or significantly engaged in the #$TechnologyIndustry or whose activities focus on that industry.") :- x_cid(a65b16526aad86).
xc_microtheory(a65b16526aad86,x_UniversalVocabularyMt).
xc_source_file(a65b16526aad86,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
