xc_kb_names(a65b16526aad86,[]).
xc_mapping_rows(a65b16526aad86,[]).
x_comment(x_PriceQuoteDocument,"The collection of all pieces of #$TextualMaterial containing information about prices. Examples include #$BidForContracts, quotes for insurance or loans, and restaurant menus with prices.") :- x_cid(a65b16526aad87).
xc_microtheory(a65b16526aad87,x_UniversalVocabularyMt).
xc_source_file(a65b16526aad87,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
