xc_mapping_rows(a65b16526aaf52,[]).
x_comment(x_programObjectRepresentsValue,"(#$programObjectRepresentsValue STRUCT VALUE) means that the program object STRUCT is a structure representing VALUE in some programming environment.") :- x_cid(a65b16526aaf53).
xc_microtheory(a65b16526aaf53,x_UniversalVocabularyMt).
xc_source_file(a65b16526aaf53,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aaf53,27623).
xc_kb_names(a65b16526aaf53,[]).
xc_mapping_rows(a65b16526aaf53,[]).
x_comment(x_programObjectTypeRepresents,"(#$programObjectTypeRepresents TYPE COL) means that the data type TYPE is used\nin some programming environment to represent instances of the collection COL.") :- x_cid(a65b16526aaf54).
xc_microtheory(a65b16526aaf54,x_UniversalVocabularyMt).
xc_source_file(a65b16526aaf54,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aaf54,27624).
