xc_mapping_rows(a65b16526aaf55,[]).
x_comment(x_softwareParameterProgramObject,"(#$softwareParameterProgramObject PARAM STRUCT) means that #$SoftwareParameter PARAM, in the context of a #$ComputerProcessRunning, has as its current in-program representation the #$ProgramObject STRUCT.") :- x_cid(a65b16526aaf56).
xc_microtheory(a65b16526aaf56,x_UniversalVocabularyMt).
xc_source_file(a65b16526aaf56,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aaf56,27627).
xc_kb_names(a65b16526aaf56,[]).
xc_mapping_rows(a65b16526aaf56,[]).
x_comment(x_ParameterValueFn,"(#$ParameterValueFn PARAM) denotes the real world object that PARAM has as a value in the context of the current state of the contextually determined #$ComputerProcessRunning.  If PARAM has a real numbered-valued data type, then (#$ParameterValueFn PARAM) will denote some instance of #$RealNumber.  This mapping of a parameter to its real world value is defined by the intentions of the program itself. ") :- x_cid(a65b16526aaf57).
xc_microtheory(a65b16526aaf57,x_UniversalVocabularyMt).
xc_source_file(a65b16526aaf57,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
xc_source_line(a65b16526aaf57,27628).
xc_kb_names(a65b16526aaf57,[]).
xc_mapping_rows(a65b16526aaf57,[]).
x_comment(x_NobelPrizeTypeByField,"A collection of types of Nobel prize.  Each instance of #$NobelPrizeTypeByField is a specialization of #$NobelPrize whose instances are all awarded in the same field.  For example, #$NobelPrizeForPhysics is an instance of NobelPrizeTypeByField -- each of its instances is awarded for excellence in physics.") :- x_cid(a65b16526aaf58).
xc_microtheory(a65b16526aaf58,x_UniversalVocabularyMt).
xc_source_file(a65b16526aaf58,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part05.krf').
