xc_kb_names(a65b16526ab63e,[]).
xc_mapping_rows(a65b16526ab63e,[]).
x_comment(x_authenticationDeviceUsed,"An instance of #$ActorSlot and a specialization of #$deviceUsed, #$authenticationDeviceUsed is used to state that  a particular authentication device is used in a particular authentication event.  <code>(#$authenticationDeviceUsed AUTH-EVT DEV)</code> means that <code>DEV</code> is an authentication device used in #$AuthenticationEvent <code>AUTH-EVT</code>.") :- x_cid(a65b16526ab63f).
xc_microtheory(a65b16526ab63f,x_UniversalVocabularyMt).
